corrected_code:
export const apiKeyRouter = router({
  revokeApiKey: protectedProcedure
    .input(z.object({ keyId: z.string() }))
    .mutation(async ({ input, ctx }) => {
      const deleted = await ctx.db.delete(apiKeysTable)
        .where(and(eq(apiKeysTable.id, input.keyId), eq(apiKeysTable.orgId, ctx.user.orgId)))
        .returning();
      if (!deleted.length) throw new TRPCError({ code: 'FORBIDDEN', message: 'API key not found or belongs to another organization' });
      return { success: true };
    }),
});
